#!/usr/bin/env bash
# ==============================================================================
# Script:  vapt_rollback.sh
# Purpose: Universal rollback executor using snapshots generated by vapt_backup.sh
# Usage:   sudo ./vapt_rollback.sh <package_name> [specific_snapshot_path]
# ==============================================================================

set -o errexit
set -o nounset
set -o pipefail

if [ "${EUID}" -ne 0 ]; then
    echo "[-] Error: Rollback must be executed with root/sudo privileges." >&2
    exit 1
fi

TARGET_PKG="${1:-}"
SPECIFIC_PATH="${2:-}"

if [ -z "${TARGET_PKG}" ]; then
    echo "[-] Usage: sudo $0 <package_name> [/optional/path/to/snapshot_dir]" >&2
    exit 1
fi

# Path resolution
if [ -n "${SUDO_USER:-}" ]; then
    USER_HOME=$(getent passwd "${SUDO_USER}" | cut -d: -f6)
else
    USER_HOME="${HOME}"
fi

BACKUP_ROOT="${USER_HOME}/update-backups/packagebackup"

# Locate target snapshot directory
if [ -n "${SPECIFIC_PATH}" ] && [ -d "${SPECIFIC_PATH}" ]; then
    SNAPSHOT_DIR="${SPECIFIC_PATH}"
else
    if [ ! -d "${BACKUP_ROOT}" ]; then
        echo "[-] Error: Backup base directory '${BACKUP_ROOT}' does not exist." >&2
        exit 1
    fi
    SNAPSHOT_DIR=$(find "${BACKUP_ROOT}" -maxdepth 1 -type d -name "${TARGET_PKG}_*" | sort -r | head -n 1 || true)
fi

if [ -z "${SNAPSHOT_DIR}" ] || [ ! -d "${SNAPSHOT_DIR}" ]; then
    echo "[-] Error: No backup snapshots found for '${TARGET_PKG}' under ${BACKUP_ROOT}" >&2
    exit 1
fi

echo "[*] Selected rollback snapshot: ${SNAPSHOT_DIR}"

CONF_ARCHIVE="${SNAPSHOT_DIR}/etc_configs.tar.gz"
MANIFEST_FILE="${SNAPSHOT_DIR}/manifest.txt"
NEW_PACKAGES_FILE="${SNAPSHOT_DIR}/new_packages.txt"

# 1. Restore Preserved .deb Binaries
DEBS=$(find "${SNAPSHOT_DIR}" -maxdepth 1 -type f -name "*.deb" | tr '\n' ' ')

if [ -n "${DEBS// /}" ]; then
    echo "[*] Restoring packages via preserved .deb archives..."
    # Install preserved .deb files together to satisfy mutual dependencies
    dpkg -i --force-downgrade ${DEBS} || {
        echo "[!] Standard install encountered dependency gaps. Resolving via apt-get -f..."
        apt-get install -f -y
    }
else
    echo "[!] No local .deb archives found in snapshot. Falling back to manifest repository downgrade..."
    if [ -f "${MANIFEST_FILE}" ]; then
        PKG_TARGETS=$(tr '\n' ' ' < "${MANIFEST_FILE}")
        apt-get install --allow-downgrades -y ${PKG_TARGETS}
    else
        echo "[-] Error: Neither .deb archives nor manifest.txt exist. Rollback aborted." >&2
        exit 1
    fi
fi

# 2. Restore Configuration Snapshots
if [ -f "${CONF_ARCHIVE}" ]; then
    echo "[*] Restoring configuration snapshots to /etc..."
    tar -xzf "${CONF_ARCHIVE}" -C /
fi

# 3. Inform operator regarding orphaned new dependencies
if [ -f "${NEW_PACKAGES_FILE}" ]; then
    ORPHANS=$(tr '\n' ' ' < "${NEW_PACKAGES_FILE}")
    if [ -n "${ORPHANS// /}" ]; then
        echo -e "\033[1;33m[NOTICE] The following packages were newly introduced during the upgrade and remain installed:\033[0m"
        echo "         ${ORPHANS}"
        echo "         If desired, purge them using: sudo apt-get purge ${ORPHANS}"
    fi
fi

echo "[+] Rollback sequence for '${TARGET_PKG}' completed successfully."